/*********************************************************************************************************************************************************
* TRIGGER HANDSHAKE
*********************************************************************************************************************************************************/

// Write Trigger
PLC_IN_TriggerReady = PLC_OUT_TriggerEnable && !PLC_IN_Acquiring && !PLC_IN_Decoding;
PLC_IN_TriggerAck = PLC_OUT_Trigger;

if(PLC_IN_TriggerReady && PLC_OUT_Trigger && !stateTrigger)
{
	if(SIM_SetAcquiringMissed)
	{
		PLC_IN_MissedAcquiring = true;
	}
	else
	{
		// Trigger Count
		triggerCount++;
		if(triggerCount > 10000)
		{
			triggerCount = 0;
		}

		byte[] TrigID = BitConverter.GetBytes(triggerCount);
		if(TrigID.Length >= 2)
        {
            // Write to PLC-Signals (change High- and Low-Byte)
            localTrigId1 = TrigID[1];
            localTrigId2 = TrigID[0];
        }

		// Reset when aquiring was successful
		PLC_IN_MissedAcquiring = false;
	}

    PLC_IN_DecodeComplete = false;

    // Reset delay timers with new trigger
    Timer_DelayResultAck = 0f;
    Timer_DelayResultID = 0f;

}
stateTrigger = PLC_OUT_Trigger;





/*********************************************************************************************************************************************************
* TIMER AQUIRING & DECODING  +  SAVE DATA
*********************************************************************************************************************************************************/

// Start Timer for Aquiring and Decoding
aquiringDecodingDone = TimeAcquiringDecoding(PLC_IN_TriggerReady && PLC_OUT_Trigger && !PLC_IN_DecodeComplete && !SIM_SetAcquiringMissed);

if(aquiringDecodingDone)
{	
	// Write data to next free position, if ResultsBuffer is enabled
	if(PLC_OUT_ResultsBufferEnable)
	{

		int i = 0;
		int j = 0;
		bool doneReadData = false;          // flag, dmc written
        bool doneReadTrigger = false;       // flag, trigger written


		#region Save Data
		// Find next free position in string array
		while(i <= 4 && !doneReadData)
		{
			// Check if buffer is full
			if(i == 4 && ReadDataSaved[i] != null)
			{
				PLC_IN_ResultBufferOverrun = true;
			}
			// Write data into next free array place
			if(ReadDataSaved[i] == null)
			{
				ReadDataSaved[i] = localReadData;    //SIM_ReadData;
				doneReadData = true;

				// Reset BufferOverrun bit, when new data was successfully written
				PLC_IN_ResultBufferOverrun = false;
			}
			i++;
		}		
		// Save data
		bufferstring1 = ReadDataSaved[0];
		bufferstring2 = ReadDataSaved[1];
		bufferstring3 = ReadDataSaved[2];
		bufferstring4 = ReadDataSaved[3];
		bufferstring5 = ReadDataSaved[4];
		#endregion


		#region Save Trigger
		// Find next free position in trigger array
		while(j <= 4 && !doneReadTrigger)
		{
			if(j == 4 && TriggerIDSaved[j] != 0)
			{
				// Trigger-Array full!
			}
			// Write trigger to next free array place
			if(TriggerIDSaved[j] == 0)
			{
				TriggerIDSaved[j] = triggerCount;
				doneReadTrigger = true;
			}
			j++;
		}

		// Save trigger data
		buffertrigger1 = TriggerIDSaved[0];
		buffertrigger2 = TriggerIDSaved[1];
		buffertrigger3 = TriggerIDSaved[2];
		buffertrigger4 = TriggerIDSaved[3];
		buffertrigger5 = TriggerIDSaved[4];		
        #endregion

	}


	// Result Buffer disabled
	else
	{
		bufferstring1 = localReadData;
		buffertrigger1 = triggerCount; //localTrigId2; //PLC_IN_TriggerID2;       // Changed High-/Low-Byte for Siemens
	}

}







/*********************************************************************************************************************************************************
* DATA READY ACKNOWLEDGE HANDSHAKE
*********************************************************************************************************************************************************/

if(PLC_IN_DecodeComplete)
{
    // Write data to PLC (always first position of data array -> FIFO)
    writeDone = WriteDataToPLC(bufferstring1, SIM_ResultData, SIM_QualityData);

    if(writeDone)
    {
        // Feedback to PLC: data ready
        PLC_IN_ResultsAvailable = true;

        PLC_IN_TriggerID1 = localTrigId1;
        PLC_IN_TriggerID2 = localTrigId2;

        // Delay ResultID
        Timer_DelayResultID += SceneObject.DeltaTime;
        if(Timer_DelayResultID > 0.1f)
        {
            PLC_IN_ResultID = (short)buffertrigger1;         
            PLC_IN_ResultCode = 7;     //ResultRead 0x01, ResultValidated = 0x02, ResultVerified = 0x03

            // Data read from PLC
            if(PLC_OUT_ResultsAck)
            {
                // Reset feedback: no data available
                PLC_IN_ResultsAvailable = false;  
                PLC_IN_DecodeComplete = false;
                aquiringDecodingDone = false;

                // Move data in array if ResultsBuffer is enabled
                if(PLC_OUT_ResultsBufferEnable)
                {
                    bufferstring1 = bufferstring2;
                    bufferstring2 = bufferstring3;
                    bufferstring3 = bufferstring4;
                    bufferstring4 = bufferstring5;
                    bufferstring5 =  null;

                    buffertrigger1 = buffertrigger2;
                    buffertrigger2 = buffertrigger3;
                    buffertrigger3 = buffertrigger4;
                    buffertrigger4 = buffertrigger5;
                    buffertrigger5 = 0;

                    // Set data ready, if data is still in buffer
                    if(bufferstring1 != null)
                    {
                        writeDone = WriteDataToPLC(bufferstring1, SIM_ResultData, SIM_QualityData);

                        PLC_IN_ResultsAvailable = true;
                    }
                }  
            }
        }

    }
}







/*********************************************************************************************************************************************************
* HELPER FUNCTIONS
*********************************************************************************************************************************************************/

// TIMER FUNCTION FOR AQUIRING DECODING
bool TimeAcquiringDecoding(bool enable)
{

	// Waiting for Trigger start
	if(!enable && !state_enabled)
	{
		PLC_IN_Acquiring = false;
		PLC_IN_Decoding = false;
		return false;
	}
	state_enabled = true;

	if(!startDecoding)
	{
		// Start aquiring
		PLC_IN_Acquiring = true;

		TimerAquiringDecoding += SceneObject.DeltaTime;
		if(TimerAquiringDecoding > 0.5f)
		{
            PLC_IN_Acquiring = false;
            startDecoding = true;
            TimerAquiringDecoding = 0;
		}
		return false;
	}

	// Start decoding
	PLC_IN_Decoding = true;

	TimerAquiringDecoding += SceneObject.DeltaTime;
	if(TimerAquiringDecoding > 0.5f)
    {
        PLC_IN_Decoding = false;
        PLC_IN_DecodeComplete = true;

        startDecoding = false;
        state_enabled = false;
        return true;
    }
	return false;	
}



// WRITE DATA
bool WriteDataToPLC(string data, string result, string quality)
{

	int codelength10 = data.Length / 10;
	int codelength1 = data.Length % 10;	
	var resultdata = "";


	// Check for Grob Script
	if(!SIM_EnableGrobScript)
	{
		resultdata = data;
	}
	else if(SIM_EnableGrobScript)
	{
		resultdata = result + quality + codelength10.ToString() + codelength1.ToString() + data + "\n";		// "0x0A" = LineFeed "\n"
	}

	PLC_IN_ResultLength = (short)resultdata.Length;

